code.perFrame:
now=gettime(0) ; sec=now-last ; last=now ;
asp=w/h ; reg07=asp ; reg08=w/200 ;

// gimme volume!
bnd=0 ;
loop(100,exec3(
assign(bnd,bnd+0.01),
assign(specvol,specvol+getspec(bnd*0.4,0,0)),
assign(oscvol,oscvol+sqrt(sqr(getosc(bnd,0,0)))))) ; 

specvol=specvol*0.92 ; oscvol=oscvol*0.92 ;
tolvol=(specvol+oscvol)*0.5 ;

// string rotation & multiply
rot1=rot1+specvol*sec*rotspd ; mul1=mul1*0.94+specvol*mulspd ;
rot2=rot2+oscvol*sec*rotspd ; mul2=mul2*0.94+oscvol*mulspd ;
rot3=rot3+tolvol*sec*rotspd ; mul3=mul3*0.94+tolvol*mulspd ;

reg00=rot1 ; reg01=mul1 ;
reg02=rot2 ; reg03=mul2 ;
reg04=rot3 ; reg05=mul3 ;

// 3D rotation
xg=xg*0.99+getspec(rand(401)*0.001,0.01,0)*xb ;
yg=yg*0.99+getspec(rand(401)*0.001,0.01,0)*yb ;
zg=zg*0.99+getspec(rand(401)*0.001,0.01,0)*zb ;
xr=xr+xg*sec*spnspd ;
yr=yr+yg*sec*spnspd ;
zr=zr+zg*sec*spnspd ;

reg10=sin(xr) ; reg11=cos(xr) ;
reg12=sin(yr) ; reg13=cos(yr) ;
reg14=sin(zr) ; reg15=cos(zr) ;

// background rotation
bg=bg*0.95+tolvol*dir ;
br=br+bg*sec ;
reg06=br

rot=reg06 ; asp=reg07 ;
zm=0.33 ; izm=1/asp-zm ;
st=sin(rot)*izm ;
ct=cos(rot)*izm*asp

asp=reg07 ; linesize=reg08 ;
sx=reg10 ; cx=reg11 ;
sy=reg12 ; cy=reg13 ;
sz=reg14 ; cz=reg15 ;
rot=reg00 ; mul=reg01 ;

code.perPoint:
// scope code ;
sipi=sqrt(sin(i*$pi)) ;
x1=sin(i*$pi*mul+rot)*sipi ;
y1=cos(i*$pi*mul+rot)*sipi ;
z1=(i-0.5)*2 ;

// 3D rotation matrices ;
x2=x1*cy-z1*sy ; z2=x1*sy+z1*cy ;
y2=y1*cx-z2*sx ; z2=y1*sx+z2*cx ;
x3=x2*cz-y2*sz ; y3=x2*sz+y2*cz ;

// 3D to 2D conversion ;

z3=1/(z2+cmr) ;
x=x3*z3*2.75 ;
y=y3*z3*2.75*asp ;
skip=below(z2,0) ;

